window.MONSTER_CHUNK_54 = [{"name":"Capramace","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"aberration","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":76,"hd":"9d8+45","hdvalue":9,"fort":9,"ref":6,"will":8,"speed":[{"type":"land","speed":50}],"melee":"bite +12 (1d8+7 plus disease), 2 hooves +7 (1d6+3)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"disease"},{"type":"rage call"}],"strength":24,"dexterity":13,"constitution":18,"intelligence":1,"wisdom":14,"charisma":5,"baseatk":6,"cmb":14,"cmb_special":"+2 vs. bull rush","cmd":25,"cmd_special":"+2 vs. bull rush","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":14},{"skill":"Perception","value":10}],"environments":["temperate plains"],"organizations":["solitary","pack (2-11)","herd (12-25)"],"treasure":"none","description_visual":"This twisted amalgamation of human and goat sports a backward-facing torso, four stubby hooves, and an empty-eyed expression on its coppery-red face.","source":"Wardens Of The Reborn Forge","special_abilities":[{"type":"Disease","kind":"Su","details":"Waste Trembles: Bite-injury; save Fort DC 19; onset 1d3 days; frequency 1 day; effect 1d3 Str and 1d3 Dex damage, target must succeed at a second Fort save or be drained of 1 point of each type of ability damage instead; cure 2 consecutive saves."},{"type":"Rage Call","kind":"Su","details":"Once per day as a standard action, a capramace can open its mouth and emit a horrible, earpiercing scream to call for its herd. Maintaining a rage call on any round after the first round is a free action and there is no limit to the duration of a sustained rage call. Non-capramaces within 120 ft. that fail a DC 18 Fortitude saving throw are deafened for as long as the capramace maintains its call and for 1d4 minutes afterward. Any other capramaces within 1 mile can hear this high-pitched cry regardless of external noise conditions, and they instinctively react by sprinting to the capramace in need, moving as fast as possible toward the capramace for as long as it maintains its rage call. A capramace moving toward the source of a rage call is treated as though it possessed the Run feat. Any capramace that comes within 60 ft. of another capramace's rage call goes wild with fear and anger, stomping about and attacking the nearest creature in sight for as long as the rage call lasts. Sound-mitigating effects such as silence or a muzzle of suppression can prevent a capramace from performing its rage call, as can effects that suffocate a capramace. Similarly, a capramace with the deafened condition cannot be affected by the rage cry of another capramace. The save DC is Constitution-based."}],"description":"Capramaces are wild, monstrous beasts native to the Mana Wastes. While their exact origins are unknown, scholars speculate that they are an unholy abomination resulting from some combination of goat, human, and the Mana Wastes' mutative energies. Farmers must be careful when removing them from farmlands for fear of startling them and awakening their terrible, deafening screams. Brave inhabitants of remote Mana Wastes settlements sometimes use capramaces as work animals, but most regard this a foolish endeavor at best.","ecology":"","habitat_society":""},{"name":"Caulborn","cr":7,"xp":3200,"alignment":"N","size":"Medium","type":"outsider","subtypes":["extraplanar"],"init":4,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"thoughtsense"}],"ac":19,"ac_touch":18,"ac_flat_footed":15,"ac_mods":"+4 deflection, +4 Dex, +1 natural","hp":76,"hd":"9d10+27","hdvalue":9,"fort":6,"ref":8,"will":13,"defensive_abilities":["premonition","psychic deflection"],"immunities":["visual effects"],"speed":[{"type":"land","speed":30}],"melee":"bite +13 (2d6+3), 2 claws +12 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"consume thoughts"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"detect thoughts"},{"spell":"read magic"}]},{"frequency":"3/day","spells":[{"spell":"charm monster"},{"spell":"daze monster"},{"spell":"hold monster"},{"spell":"hypnotic pattern"},{"spell":"vampiric touch"}]},{"frequency":"1/week","spells":[{"spell":"plane shift","details":"willing targets only"}]}],"strength":16,"dexterity":19,"constitution":16,"intelligence":25,"wisdom":20,"charisma":19,"baseatk":9,"cmb":12,"cmd":30,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Iron Will"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Appraise","value":12},{"skill":"Bluff","value":14},{"skill":"Intimidate","value":14},{"skill":"Knowledge (all)","value":14},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":11},{"skill":"Use Magic Device","value":9}],"languages":["Abyssal","Aklo","Aquan","Celestial","Common","Draconic","Giant","Infernal","telepathy 100 ft."],"sq":[{"type":"cooperative scrying"},{"type":"hive mind"}],"environments":["any"],"organizations":["solitary","pair","colony (3-12)"],"treasure":"double","description_visual":"This creature has a split-jawed mouth, a hoodlike growth on its head, and two hideously elongated fingers on each hand.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Consume Thoughts","kind":"Ex","details":"A caulborn can consume the thoughts of a willing, helpless, or fascinated creature with a touch attack. If the target fails a DC 18 Will save, the caulborn can alter the victim's memory as if using modify memory. This process deals 1d4 points of Intelligence and Wisdom damage to the target. The save DC is Charisma-based."},{"type":"Cooperative Scrying","kind":"Sp","details":"Three or more caulborn joining hands can scry on a place or creature as if using the scrying spell (DC 20), but with no limit to the spell's duration so long as at least three of the caulborn involved continue to join hands and concentrate. This ability functions at CL 7th (or at the highest CL available to the most powerful caulborn in the group). The save DC is Charisma-based, adjusted by the modifier of the caulborn with the highest Charisma score."},{"type":"Hive Mind","kind":"Ex","details":"As long as there are at least two caulborn within 300 ft. of each other, if one caulborn in the group is aware of a particular danger, they all are. No caulborn in a group is considered flanked or flat-footed unless all of them are."},{"type":"Psychic Deflection","kind":"Su","details":"A caulborn adds its Charisma modifier as a deflection bonus to its AC. The caulborn loses this bonus when unconscious."},{"type":"Thoughtsense","kind":"Su","details":"A caulborn notices and locates living, conscious creatures within 60 ft., just as if it possessed the blindsight ability. Spells such as nondetection or mind blank make an affected creature undetectable by this sense."}],"description":"Caulborn are a race of telepathic prophets and historians who subsist on the psychic energy of others. They wander the planes in search of new facts and concepts to add to the pulsating brain-sacks that serve as their collective memories. When a band of caulborn find a particularly interesting site, they settle down to dwell there for many years until they feel that they have learned all there is to know about the location.\n\nA caulborn is literally a creature of the mind. Its body is self-sustaining, and it exists solely to record and catalogue new thoughts. While they are not evil, caulborn have little interest in alliances or friendship with other races.","ecology":"","habitat_society":""},{"name":"Caustic Stalker","cr":7,"xp":3200,"alignment":"N","size":"Medium","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":12,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":19,"ac_flat_footed":10,"ac_mods":"+8 Dex, +1 dodge","hp":73,"hd":"7d10+35","hdvalue":7,"fort":10,"ref":13,"will":4,"defensive_abilities":["amorphous"],"dr":"5/-","immunities":["acid","elemental traits"],"weaknesses":["vulnerable to wind"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"2 slams +15 (1d6 plus chemical burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"15-ft. cone, 5d6 acid damage plus poison, Reflex DC 18 half, usable every 1d4 rounds"},{"type":"chemical burn","details":"1d6, DC 18"}],"dexterity":27,"constitution":20,"intelligence":5,"wisdom":14,"charisma":11,"baseatk":7,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":26},{"skill":"Perception","value":12},{"skill":"Stealth","value":18}],"languages":["Auran"],"sq":[{"type":"misty form"}],"environments":["any underground"],"organizations":["solitary","pair","smog (3-10)"],"treasure":"incidental","description_visual":"Reaching hands, a fierce and eerie visage, and a powerfully abrasive stench all stem from this hissing cloud of churning gases.","source":"The Emerald Spire","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"In addition to taking acid damage, any creature harmed by a caustic stalker's breath weapon must succeed at an additional DC 18 Fortitude saving throw or be affected by caustic creep poison. Caustic Creep-inhaled; save Fort DC 18; frequency 1/round for 4 rounds; effect 1d4 Con; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Chemical Burn","kind":"Su","details":"Any creature struck by the caustic stalker, or that strikes it with a natural weapon or unarmed attack, is affected as if by the burn special attack, but takes acid damage instead of fire damage. The chemical burn persists for multiple rounds, just as a normal burn, but can be ended early if the affected creature is doused in at least 1 gallon of liquid (requiring a full-round action from the victim or another creature) or fully submerges itself in water."},{"type":"Misty Form","kind":"Su","details":"A caustic stalker's body is composed of a semisolid chemical mist similar to thick foam. The caustic stalker doesn't have a Strength score and cannot manipulate or wear solid objects. This form grants it the amorphous defensive ability, and enables it to move through areas as small as 1 inch in diameter with no reduction to its speed. A caustic stalker cannot enter water or other fluids, and is treated as a creature two size categories smaller than its actual size (Tiny for most caustic stalkers) for the purposes of how wind affects it."},{"type":"Vulnerable to Wind","kind":"Ex","details":"A caustic stalker takes damage every round that it's exposed to stronger than moderate winds: 1d6 points of damage for strong winds, 2d6 points of damage for severe winds, and an additional 1d6 points of damage for each wind force category beyond severe. Gust of wind is considered severe wind for this ability. A caustic stalker cannot use its breath weapon while being affected by stronger than moderate winds and for 1 minute afterward."}],"description":"Though caustic stalkers arise from pockets of poisonous gas in the Plane of Air, they far prefer to congregate amid the great heat and pressure where the Plane of Earth and Plane of Fire meet. These conditions are also common in the depths of many worlds on the Material Plane. Caustic stalkers are usually content to drift amid the searing rocks and toxic fumes of volcanic depths, but occasionally emerge into more spacious areas. When they emerge, they are quick to lash out at anything that disturbs their explorations, especially if the area is windy.","ecology":"","habitat_society":""},{"name":"Chaos Beast","cr":7,"xp":3200,"alignment":"CN","size":"Medium","type":"outsider","subtypes":["chaotic","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+2 Dex, +1 dodge, +7 natural","hp":85,"hd":"9d10+36","hdvalue":9,"fort":9,"ref":8,"will":4,"defensive_abilities":["amorphous","resistant to transformation"],"sr":18,"speed":[{"type":"land","speed":20}],"melee":"4 claws +13 (1d6+3 plus corporeal instability)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":15,"constitution":16,"intelligence":10,"wisdom":12,"charisma":11,"baseatk":9,"cmb":12,"cmd":25,"cmd_special":"can't be tripped","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Toughness"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":14,"special":"+10 jump"},{"skill":"Climb","value":15},{"skill":"Escape Artist","value":14},{"skill":"Perception","value":13},{"skill":"Stealth","value":14},{"skill":"Swim","value":15}],"environments":["any"],"organizations":["solitary","invasion (2-5)"],"treasure":"none","description_visual":"This thing is a horrid mass of barbed tentacles, glaring eyes, and gnashing teeth, twisting upon itself and reshaping into new forms.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Corporeal Instability","kind":"Su","details":"Claw-contact (curse); save Fort DC 17; effect amorphous body and 1 Wisdom drain per round; cure 3 consecutive saves. The save DC is Con-based. A creature cursed with an amorphous body becomes a spongy, shapeless mass. Unless the victim manages to control the effect, its shape constantly melts, flows, writhes, and boils. An affected creature is unable to hold or use any item. Clothing, armor, helmets, and rings become useless. Large items worn or carried-armor, backpacks, even shirts-hamper more than help, reducing the victim's Dexterity score by 4. Speed is reduced to 10 ft. or one-quarter normal, whichever is less. The victim gains the amorphous quality, but cannot cast spells or use magic items, and it attacks blindly, unable to distinguish friend from foe (-4 penalty on attack rolls and a 50% miss chance, regardless of the attack roll). A victim can temporarily regain its own shape by taking a standard action to attempt a DC 15 Will save (this check DC doesn't vary for a chaos beast with different Hit Dice or ability scores). A success reestablishes the creature's normal form for 1 minute. Spells that change the victim's shape (such as alter self, beast shape, elemental body, and polymorph) don't remove the curse, but hold the creature in a stable form (which might not be its own form, depending on the spell) and prevent additional Wisdom drain for the duration of the spell; shapechange and stoneskin have a similar effect. The victim takes 1 point of Wisdom drain from mental shock every round that it ends its turn in an amorphous shape-upon being drained to 1 Wisdom, further Wisdom drain ceases and the amorphous body effect is permanent until removed via magic (no further number of saving throws can cure the condition at this time)."},{"type":"Resistant to Transformation","kind":"Ex","details":"Transmutation effects, such as polymorphing or petrification, force a chaos beast into a new shape, but at the start of its next turn, it immediately returns to its normal form as a free action."}],"description":"A chaos beast's form changes without any goal or purpose.\n\nThough at any particular second a chaos beast may appear to have dozens of limbs, whether claws, tentacles, stingers, and so on, the lightning-quick shifts of its body mean most of these are gone before it has a chance to use them, and its attacks are always treated as claws regardless of the creature's appearance.","ecology":"","habitat_society":""},{"name":"Charda","cr":7,"xp":3200,"alignment":"CN","size":"Small","type":"monstrous humanoid","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"120 ft."}],"ac":20,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+2 Dex, +7 natural, +1 size","hp":85,"hd":"9d10+36","hdvalue":9,"fort":7,"ref":10,"will":7,"defensive_abilities":["ferocity"],"immunities":["cold","poison"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":60}],"melee":"bite +13 (1d6+3 plus 1d6 cold), 4 claws +14 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"black bile"}],"strength":16,"dexterity":15,"constitution":19,"intelligence":11,"wisdom":12,"charisma":8,"baseatk":9,"cmb":11,"cmb_special":"+8 vs. bull rush and trip","cmd":23,"feats":[{"feat":"Combat Expertise","type":"bonus"},{"feat":"Improved Bull Rush"},{"feat":"Improved Trip"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Intimidate","value":6},{"skill":"Knowledge (religion)","value":4},{"skill":"Perception","value":13},{"skill":"Stealth","value":18},{"skill":"Survival","value":10},{"skill":"Swim","value":18}],"languages":["Aklo","Undercommon"],"sq":[{"type":"amphibious"},{"type":"cold vigor"},{"type":"overwhelming"}],"environments":["cold aquatic","cold underground"],"organizations":["solitary","pair","gang (3-5)","tribe (6-14)"],"treasure":"standard","description_visual":"Armored in dense, bony plates, this four-armed creature drools wretched strings of black bile from its fanged maw.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Black Bile","kind":"Su","details":"A charda's body seethes with freezing black bile. Its supernaturally cold, black bile is the source of the additional cold damage when a charda bites a creature. As a standard action, a charda can expel its full store of bile as a breath weapon that can take the form of a 60-foot line or a 30-foot cone. All creatures in this area take 8d6 points of cold damage (DC 18 Reflex half). A charda can use this breath weapon once every 1d4 rounds-while its black bile is recharging, it doesn't deal additional cold damage with its bite. The save DC is Constitution-based."},{"type":"Cold Vigor","kind":"Ex","details":"When a charda is in a cold environment, it becomes more animated and gains a +1 racial bonus on attack rolls and weapon damage rolls."},{"type":"Overwhelming","kind":"Ex","details":"A charda gains a +8 racial bonus on bull rush and trip attacks."}],"description":"In the darkest depths of the earth, in strange frozen rivers and subterranean lakes of frigid black water dwell the mysterious and ferocious chardas. These xenophobic humanoids rarely venture far from their domains, settling in small tribes and building rocky huts underwater or muddy domes along the subterranean shore.\n\nA typical charda stands just under 4 ft. tall but weighs 250 pounds. Chardas reproduce by laying eggs in small clutches of two to four, which they bury among rocks offshore. Females fiercely protect their own clutches, but show no predisposition toward protecting the clutches of other chardas, even those within their tribe.\n\nDevoutly religious, chardas prefer to worship gods of war or cold. They hunt in small packs composed of both males and females. Hunting and slaying help determine an individual's power within the group. Chardas often engage in infanticide and cannibalism. While they patrol their territories in groups, they fight individually with little strategy or structure. Chardas don't assist each other with their kills, as they perceive aid as a weakness and a dishonor to both themselves and their foes.","ecology":"","habitat_society":""},{"name":"Chimera","cr":7,"xp":3200,"alignment":"CE","size":"Large","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+1 Dex, +9 natural, -1 size","hp":85,"hd":"9d10+36","hdvalue":9,"fort":9,"ref":7,"will":6,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"poor"}],"melee":"bite +12 (2d6+4), bite +12 (1d8+4), gore +12 (1d8+4), 2 claws +12 (1d6+4)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon"}],"strength":19,"dexterity":12,"constitution":17,"intelligence":4,"wisdom":13,"charisma":10,"baseatk":9,"cmb":14,"cmd":25,"cmd_special":"+4 vs. trip","feats":[{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":2},{"skill":"Perception","value":10},{"skill":"Stealth","value":4,"special":"+8 in scrubland or brush"}],"languages":["Draconic"],"environments":["temperate hills"],"organizations":["solitary","pair","pride (3-6)","flight (7-12)"],"treasure":"standard","description_visual":"This winged monster has the body of a lion, though two more heads flank its central feline one-a dragon and a horned goat.","source":"PFRPG Bestiary","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A chimera's breath weapon depends on the color of its dragon head, as summarized on the table below. Regardless of its type, a chimera's breath weapon is usable once every 1d4 rounds, deals 6d8 points of damage, and allows a DC 17 Reflex save for half damage. The save DC is Constitution-based. To determine a chimera's head color and breath weapon randomly, roll 1d10 and consult the table below. d10 Head Color Breath Weapon 1-2 Black 40-foot line of acid 3-4 Blue 40-foot line of lightning 5-6 Green 20-foot cone of acid 7-8 Red 20-foot cone of fire 9-10 White 20-foot cone of cold."}],"description":"Chimeras are monstrous creatures born of primordial evil. Hateful and hungry, they hunt on the ground or in the air. A chimera's dragon head may be of any evil dragon type, with the corresponding breath weapon, and its wings usually match the scales on its head. Chimeras speak with three overlapping voices, but rarely do so, typically only when playing toady to a more powerful creature. A chimera is 5 ft. tall at the shoulder, nearly 10 ft. long, and weighs 700 pounds. Chimeras prefer meat but can subsist on vegetable matter if necessary (although being forced to do so generally leaves the beasts more ill-tempered than usual). Their flight means they can pick and choose their prey, and they usually hunt a large area in search of easy food. They are too stupid and belligerent to acquire followers, though sometimes a tribe of kobolds might give them offerings. Conversely, they are just intelligent and stubborn enough that they make poor pets, and only a significantly more powerful creature can keep them submissive. They may form equal partnerships with a respectful humanoid or similar creature, and even consent to be used as a mount. A pride of chimeras is very leonine in its hierarchy, with a dominant male leading the group and most of the hunting done by the females. A solitary chimera may be a young male or a female with cubs nearby.","ecology":"","habitat_society":""},{"name":"Chuul","cr":7,"xp":3200,"alignment":"CE","size":"Large","type":"aberration","subtypes":["aquatic"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+3 Dex, +10 natural, -1 size","hp":85,"hd":"10d8+40","hdvalue":10,"fort":7,"ref":6,"will":9,"immunities":["poison"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":20}],"melee":"2 claws +14 (2d6+7 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"2d6+7"},{"type":"paralytic tentacles"}],"strength":25,"dexterity":16,"constitution":18,"intelligence":10,"wisdom":14,"charisma":5,"baseatk":7,"cmb":15,"cmb_special":"+4 vs. grapple","cmd":28,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Knowledge (nature)","value":8},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":9},{"skill":"Stealth","value":9},{"skill":"Swim","value":28}],"languages":["Common (sometimes Undercommon for subterranean variants)"],"sq":[{"type":"amphibious"}],"environments":["temperate swamps"],"organizations":["solitary","pair","pack (3-6)"],"treasure":"standard","description_visual":"This lobster-like creature has a thick armored shell. A pair of tiny eyes gleams above a mouth full of writhing tentacles.","source":"PFRPG Bestiary","special_abilities":[{"type":"Paralytic Tentacles","kind":"Ex","details":"A chuul can transfer a grappled victim from a claw to its tentacles as a move action. The tentacles grapple with the same strength as the claw but deal no damage, instead exuding a paralytic secretion. Anyone held in the tentacles must succeed on a DC 19 Fortitude save each round on the chuul's turn or be paralyzed for 6 rounds. The save DC is Constitution-based. While held in the tentacles, paralyzed or not, a victim automatically takes 1d8+7 points of damage each round from the creature's mandibles."}],"description":"Chuuls are armored, crustacean-like predators that lurk beneath the surfaces of shallow ponds and mires, bursting from concealment to snatch up prey in their chitinous pincers and then paralyzing them with their mouth tentacles before eating them alive.\n\nChuuls are excellent swimmers but prefer to attack land-bound creatures or those wallowing in shallow water. Once they seize their victims, chuuls often drag grappled foes back into deep water to drown them.\n\nLizardfolk are by far the chuul's favorite prey, though those pale chuul breeds that live underground prefer morlocks, duergar, unwary drow, and other unfortunates who get too close to their subterranean waterways-with the exception of troglodytes, whose flavor chuuls find particularly offensive.\n\nChuuls are surprisingly intelligent, leading many to speculate fruitlessly on their origins and motivations.\n\nThey speak a chittering, burbling dialect of Common, but few are inclined to speak to those outside their race, and if chuul society exists beyond their frenzied mating season, humanoids have yet to record it. Instead, chuul intellects seem entirely devoted to seeking out the perfect ambush sites to attack other intelligent creatures and decorating their elaborate lairs with trophies from their kills. Though the chuuls themselves seem uninterested in using tools of any kind, they have an almost compulsive need to collect keepsakes from their victims.\n\nA typical chuul is 8 ft. tall and weighs 650 pounds.","ecology":"","habitat_society":""},{"name":"Criosphinx","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"magical beast","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":9,"ac_flat_footed":20,"ac_mods":"+11 natural, -1 size","hp":85,"hd":"10d10+30","hdvalue":10,"fort":10,"ref":7,"will":4,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"2 claws +15 (1d6+6), gore +16 (2d4+6/19-20)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"swooping charge","details":"gore, 4d4+12"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"speak with animals"}]}],"strength":23,"dexterity":10,"constitution":17,"intelligence":12,"wisdom":12,"charisma":11,"baseatk":10,"cmb":17,"cmb_special":"+2 vs. bull rush","cmd":27,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (gore)"},{"feat":"Power Attack"},{"feat":"Skill Focus (Intimidate)"},{"feat":"Weapon Focus (gore)"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Fly","value":1},{"skill":"Intimidate","value":16},{"skill":"Perception","value":10}],"languages":["Common","Sphinx","speak with animals"],"environments":["warm deserts","warm hills"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature has the wings of a bird, the body of a lion, and the head of a ram with sad, wise eyes.","group":"Sphinx","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Swooping Charge","kind":"Ex","details":"A charging criosphinx deals 4d4+12 points of damage with its gore attack. A flying criosphinx who drops at least 20 ft. in altitude as part of a charge deals 6d4+18 points instead."}],"description":"Perhaps the least leonine of all sphinxes, the ram-headed criosphinx lacks the intellect of androsphinxes and gynosphinxes, but still outmatches the dim-witted hieracosphinxes. Like hieracosphinxes and androsphinxes, criosphinxes are always male. At the start of a battle, a criosphinx lowers its horns and crashes into foes, clawing enemies it has engaged. It favors charging down on foes from great heights.\n\nCriosphinxes crave wealth over nearly all other things, habitually extorting tolls for safe passage from any who pass their lands. Groups who cannot pay must yield one of their\n\nnumber or a pair of mounts for the criosphinx's meal- single travelers must fight or die. Unlike gynosphinxes, no mere riddle suffices-only the shine of metal or the gleam of jewels can satisfy a criosphinx. Little can convince a criosphinx to part with even a single coin save the lust that its kind bears for the gynosphinx. Criosphinxes crave mating with gynosphinxes above all else, and pay well for the whereabouts of a female, or better yet, a well-crafted riddle that might impress one. For their part, gynosphinxes prefer to have little to do with what they mock as the sheep of sphinxes, though they sometimes lower themselves to a brief assignation in the rare event a criosphinx manages to impress them with wealth or wit.\n\nSome criosphinxes set themselves as soothsayers of the desert, trading upon the storied wisdom of androsphinxes and gynosphinxes to deceive gullible travelers. Like their more blustering brethren, they seek wealth from passersby, but for the purposes of dispersing information rather than in exchange for safe passage. Such reliable information as they possess usually comes from idle conversation with the creatures of the desert, with criosphinxes using their inborn ability to speak with animals. A criosphinx lacking in sound information usually fabricates a pleasing lie.\n\nCriosphinxes detest hieracosphinxes, regarding them as little more than beasts and a disgrace to their noble race. They drive off their falcon-headed cousins with mock-charges and posturing, escalating to full-f ledged attacks if ignored. Androsphinxes they view with mixed fear and respect, and gynosphinxes with disdain and lust.","ecology":"","habitat_society":""},{"name":"Deinotherium","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"animal","init":-1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":7,"ac_flat_footed":19,"ac_mods":"-1 Dex, +12 natural, -2 size","hp":92,"hd":"8d8+56","hdvalue":8,"fort":12,"ref":5,"will":3,"speed":[{"type":"land","speed":30}],"melee":"gore +13 (2d6+9), slam +13 (1d8+9)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"sweep"},{"type":"trample","details":"2d8+13, DC 23"}],"strength":29,"dexterity":9,"constitution":22,"intelligence":2,"wisdom":13,"charisma":4,"baseatk":6,"cmb":12,"cmd":24,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":11},{"skill":"Swim","value":13}],"environments":["any forests","any plains"],"organizations":["solitary","pair","family (2 adults and 1 calf)"],"treasure":"none","description_visual":"This creature resembles an elephant, though it has a shorter, thicker trunk and sharp, downward-curving tusks.","group":"Megafauna","source":"AP 91","special_abilities":[{"type":"Sweep","kind":"Ex","details":"A deinotherium can sweep a target with its downward-curving tusks and knock the victim to the ground. As part of a charge, a deinotherium can move up to twice its base speed in a straight line and make a gore attack at any point during its movement. If this attack is successful, the target is knocked prone and the deinotherium can deal damage with its trample attack before continuing its movement."}],"description":"Deinotheriums are regal beasts of the same evolutionary family as the elephant, though with a shorter temper that far exceeds that of their more docile cousins. These creatures are known to attack with very little provocation, charging and sweeping a target under their gigantic ft. to trample it to death. A typical deinotherium stands approximately 12 ft. tall at the shoulder, measures 25 ft. from trunk to tail, and weighs 30,000 pounds.\n\nWhile deinotheriums are herbivores, their quick tempers have given them a reputation as man-eaters. The downward-swooping tusks under a deinotherium's mouth are used to dig for roots and tubers that it can scoop up and devour using its prehensile trunk. It also uses its curved tusks to hook tree branches and pull them close to allow for easier feeding. The trunk itself is much shorter and wider than that of an elephant, and its huge nasal passages give the creature an acute sense of smell.\n\nDeinotheriums are not herd creatures, generally grouping only into small family packs of a calf and its parents. A mother usually gives birth to only a single calf, and will fiercely protect it well into its adult life. The father remains with the mother and calf until the calf reaches maturity, then leaves to find a new mate.","ecology":"","habitat_society":""},{"name":"Dire Bear","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"animal","init":5,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":95,"hd":"10d8+50","hdvalue":10,"fort":12,"ref":8,"will":2,"speed":[{"type":"land","speed":40}],"melee":"2 claws +13 (1d6+7 plus grab), bite +13 (1d8+7)","space":"10 ft.","reach":"5 ft.","strength":25,"dexterity":13,"constitution":21,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":7,"cmb":10,"cmd":20,"feats":[{"feat":"Endurance"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":12},{"skill":"Swim","value":19}],"environments":["cold forests"],"organizations":["solitary","pair"],"treasure":"incidental","description_visual":"Spittle drips from this feral bear's roaring maw, and its matted fur is broken in places by wicked, bony growths.","group":"Bear","source":"PFRPG Bestiary","description":"Larger, more aggressive, and far more deadly than its lesser cousins, the dire bear (known to barbarian tribes variously as the cave bear or the short-faced bear) is a primeval menace indeed.\n\nThis behemoth avoids more civilized reaches of the world, preferring to dwell in remote wilderness locations.\n\nA dire bear is a rare and terrifying sight- especially to those not used to normal bears.\n\nUnlike most bears, a dire bear is short-tempered and swift to anger when confronted with intruders in its territory.\n\nLike a grizzly, a dire bear attempts to subdue or kill with its claws.\n\nHowever, a dire bear is far more likely (and willing) to begin biting a grabbed foe.","ecology":"","habitat_society":""},{"name":"Dosojin","cr":7,"xp":3200,"alignment":"NG","size":"Medium","type":"outsider","subtypes":["kami","native"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+3 Dex, +7 natural","hp":85,"hd":"10d10+30","hdvalue":10,"hp_mods":["fast healing 4"],"fort":10,"ref":6,"will":3,"dr":"5/cold iron","immunities":["bleed","mind-affecting effects","petrification","polymorph"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30}],"melee":"2 slams +13 (1d6+2)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"know direction"},{"spell":"misdirection"},{"spell":"speak with plants"}]},{"frequency":"1/day","spells":[{"spell":"locate object"},{"spell":"mirage arcana"},{"spell":"nondetection"}]},{"frequency":"3/day","spells":[{"spell":"dispel magic"},{"spell":"fog cloud"},{"spell":"longstrider"},{"spell":"pass without trace"},{"spell":"quickened invisibility"},{"spell":"stone shape"}]}],"strength":15,"dexterity":17,"constitution":16,"intelligence":12,"wisdom":14,"charisma":17,"baseatk":10,"cmb":1,"cmd":11,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Quicken Spell- Like Ability (invisibility)"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Diplomacy","value":16},{"skill":"Disguise","value":16,"special":"+36 as statue"},{"skill":"Handle Animal","value":16},{"skill":"Knowledge (nature)","value":14},{"skill":"Perception","value":4},{"skill":"Sense Motive","value":19},{"skill":"Survival","value":15}],"languages":["Common","speak with plants","telepathy 100 ft."],"sq":[{"type":"merge with ward"},{"type":"ward","details":"roads or trails"}],"environments":["any land"],"organizations":["solitary","mated pair","cloister (3-10)"],"treasure":"standard","description_visual":"This ancient, weathered statue of a venerable monk with a shaven head possesses an air of both reverence and patience.","group":"Kami","source":"AP 52","special_abilities":[{"type":"Manipulate Path","kind":"Su","details":"As a standard action, a dosojin can alter the structure and stability of its ward, making travel along its road or trail either easier or harder for specific groups of travelers. Helping travelers in this way makes a dosojin's ward sturdier and more straightforward, allowing creatures to reach their destination in half the time they would normally take (though this doesn't grant a bonus to creatures' movement speeds in combat). If a dosojin instead chooses to hinder travelers, it creates unexpected twists and turns within its ward, turning the path into difficult terrain and so causing travelers to take twice as long as they normally would to reach their destination. These effects last as long as the targets stay within the boundaries of the dosojin's ward."},{"type":"Mimic Statue","kind":"Su","details":"As a standard action, a dosojin can assume the appearance of any Medium-sized statue, such as a stone marker, a religious icon, or a sculpture carved into the side of a cliff. A dosojin's body is hard and has the texture of rough stone no matter what appearance it takes. A dosojin gains a +20 racial bonus on Disguise checks when imitating a statue in this manner."}],"description":"Dosojins are kami that take the form of stone icons and watch over roads and trails. They are often found in statue form at the edges of villages, along mountain passes, at the beginnings of tunnels and other major\n\nworks of roadway construction, or at simple country crossroads. In urban areas, dosojins can sometimes be found on street corners and near bridges. They serve as the guardians of travelers, keeping the malicious and malevolent off the paths they diligently watch over. Wise travelers know to seek a dosojin's blessing before traveling upon its ward, for falling out of favor with the kami of travel is a sure way to become lost or hampered. Pious mortal couples also seek out dosojin for their own reasons, as the kami are often regarded as patrons of fertility, and are known for their habit of choosing mates and standing beside one another for their entire lives. In many regions, the blessing of a dosojin is believed to ensure a long and happy marriage, as well as many healthy children.\n\nThe average dosojin stands about 4-1/2 ft. tall and weighs upward of 400 pounds.\n\nEcology\n\nAs creatures that symbolize travel and connections, dosojins straddle the line between the lands of the civilized and the wild, often with one foot literally in each. Dosojins spend most of their time guarding their chosen sites in the form of nondescript statues and way markers, meditating motionlessly for seasons at a time. While semi-social dosojins within cities and other settlements are not uncommon, the majority of these kami stand along remote and secluded roads, going to great lengths to ensure that their true identity isn't known. It isn't uncommon for dosojins to create false duplicates of themselves using their stone shape ability, and these misleading markers inspire a certain amount of faith among those who look out for the kami of roads, as one can rarely tell if a sculpture is a dosojin by looks alone. A dosojin requires no sustenance, but it isn't uncommon for travelers to leave offerings for a silent watcher, usually tributes of fruits, nuts, and potables, gifts that the kami gladly shares with hungry travelers, happy to inspire such good faith among passersby and to foster a system of give-and-take between strangers.\n\nDosojins are fond of the creatures that traverse their roads and trails, and maintain the roadways they guard to ensure both the ward's survival and the safe travel of the voyagers that traverse it. Though they have an affinity for the creatures that constructed their roadways, dosojins still protect their wards with the aggressive righteousness typical of all kami, and scarcely hesitate when faced with an oni or other evildoer seeking to disrupt the balance. Dosojin have little patience for those who litter on their roadways or unnecessarily obstruct the paths, and they take it upon themselves to discipline those they deem worthy of punishment. Rarely violent in an overt sense, dosojins\n\nprefer to use their magic in order to trick travelers into becoming lost, letting the wilds they travel through become the primary instruments of their demise. Dosojins prove quite deadly to those who fail to show kami proper respect, as they use their powers of illusion to lead troublesome caravans into impassible ravines and destructive oni onto unsound, derelict bridges.\n\nHabitat & Society\n\nDosojins are odd among kami in that they are known to select mates from among their own kind, and it isn't uncommon to see two seemingly redundant statues standing next to one another near a trailhead or fork in the road. While they don't reproduce in any typical sense of the word, dosojins are nonetheless sought out by mortal couples hoping to conceive, as many people see the kami as symbols of fertility. However, most scholars agree that dosojins don't collaborate in this way to foster fecundity, but rather act as symbols of camaraderie and companionship for travelers on their roads, encouraging teamwork and cooperation among groups of diverse individuals with a shared goal.\n\nWhile most dosojins are content to watch over particular highways or roads for their entire existences and act as helpful guardians for most passersby, some choose instead to act as appraisers of travelers' skills and bravery. Cunning individuals that indulge in acts of trickery more often than their tamer brethren, these rogue dosojins craft obstacles and trials for travelers they deem worthy of the challenge. The tests are not meant to substantially impede voyagers, and are simply forms of innocent fun that a dosojin uses to gauge the strength and resolve of various wayfarers. Those who surpass a dosojin's challenges (which usually take the form of puzzles or illusions) earn the kami's respect and the assurance of safe travel throughout the rest of its domain, while those who avoid the obstacle or overcome it through brutish and witless means garner only scorn. Careful travelers know to watch out for the statuelike kami when making their way along potentially protected roads, as the guardians expect voyagers to act honorably and respectfully while travelling upon their paths. Some of the most important mandates to keep in mind when interacting with dosojin and walking through their territories are as follows.\n\n• Mortals who respect the land and its laws shall know no harm.\n\n• Mortals who fail to show proper reverence for tradition shall not pass by a dosojin upon the first attempt.\n\n• Mortals who actively harm the natural world shall be cursed to wander it.\n\n• Mortals who stray from a dosojin's path to do harm should not expect to find that path ever again.","ecology":"As creatures that symbolize travel and connections, dosojins straddle the line between the lands of the civilized and the wild, often with one foot literally in each. Dosojins spend most of their time guarding their chosen sites in the form of nondescript statues and way markers, meditating motionlessly for seasons at a time. While semi-social dosojins within cities and other settlements are not uncommon, the majority of these kami stand along remote and secluded roads, going to great lengths to ensure that their true identity isn't known. It isn't uncommon for dosojins to create false duplicates of themselves using their stone shape ability, and these misleading markers inspire a certain amount of faith among those who look out for the kami of roads, as one can rarely tell if a sculpture is a dosojin by looks alone. A dosojin requires no sustenance, but it isn't uncommon for travelers to leave offerings for a silent watcher, usually tributes of fruits, nuts, and potables, gifts that the kami gladly shares with hungry travelers, happy to inspire such good faith among passersby and to foster a system of give-and-take between strangers.\n\nDosojins are fond of the creatures that traverse their roads and trails, and maintain the roadways they guard to ensure both the ward's survival and the safe travel of the voyagers that traverse it. Though they have an affinity for the creatures that constructed their roadways, dosojins still protect their wards with the aggressive righteousness typical of all kami, and scarcely hesitate when faced with an oni or other evildoer seeking to disrupt the balance. Dosojin have little patience for those who litter on their roadways or unnecessarily obstruct the paths, and they take it upon themselves to discipline those they deem worthy of punishment. Rarely violent in an overt sense, dosojins\n\nprefer to use their magic in order to trick travelers into becoming lost, letting the wilds they travel through become the primary instruments of their demise. Dosojins prove quite deadly to those who fail to show kami proper respect, as they use their powers of illusion to lead troublesome caravans into impassible ravines and destructive oni onto unsound, derelict bridges.","habitat_society":"Dosojins are odd among kami in that they are known to select mates from among their own kind, and it isn't uncommon to see two seemingly redundant statues standing next to one another near a trailhead or fork in the road. While they don't reproduce in any typical sense of the word, dosojins are nonetheless sought out by mortal couples hoping to conceive, as many people see the kami as symbols of fertility. However, most scholars agree that dosojins don't collaborate in this way to foster fecundity, but rather act as symbols of camaraderie and companionship for travelers on their roads, encouraging teamwork and cooperation among groups of diverse individuals with a shared goal.\n\nWhile most dosojins are content to watch over particular highways or roads for their entire existences and act as helpful guardians for most passersby, some choose instead to act as appraisers of travelers' skills and bravery. Cunning individuals that indulge in acts of trickery more often than their tamer brethren, these rogue dosojins craft obstacles and trials for travelers they deem worthy of the challenge. The tests are not meant to substantially impede voyagers, and are simply forms of innocent fun that a dosojin uses to gauge the strength and resolve of various wayfarers. Those who surpass a dosojin's challenges (which usually take the form of puzzles or illusions) earn the kami's respect and the assurance of safe travel throughout the rest of its domain, while those who avoid the obstacle or overcome it through brutish and witless means garner only scorn. Careful travelers know to watch out for the statuelike kami when making their way along potentially protected roads, as the guardians expect voyagers to act honorably and respectfully while travelling upon their paths. Some of the most important mandates to keep in mind when interacting with dosojin and walking through their territories are as follows.\n\n• Mortals who respect the land and its laws shall know no harm.\n\n• Mortals who fail to show proper reverence for tradition shall not pass by a dosojin upon the first attempt.\n\n• Mortals who actively harm the natural world shall be cursed to wander it.\n\n• Mortals who stray from a dosojin's path to do harm should not expect to find that path ever again."},{"name":"Dracolisk","cr":7,"xp":3200,"race":"Half-black dragon basilisk","alignment":"N","size":"Medium","type":"dragon","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":9,"ac_flat_footed":21,"ac_mods":"-1 Dex, +12 natural","hp":73,"hd":"7d10+35","hdvalue":7,"fort":12,"ref":4,"will":8,"immunities":["acid","sleep","paralysis"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"bite +14 (1d8+7), 2 claws +14 (1d4+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"60-foot line of acid, 7d6 acid damage, Reflex DC 18 half"},{"type":"gaze","details":"DC 18"}],"strength":24,"dexterity":8,"constitution":21,"intelligence":4,"wisdom":13,"charisma":13,"baseatk":7,"cmb":18,"cmd":30,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":9},{"skill":"Perception","value":14},{"skill":"Stealth","value":13}],"environments":["temperate swamps","temperate underground"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"This six-legged dragon flaps its massive wings as it lowers its head to glare with hideous glowing eyes.","group":"Half-Dragon","source":"PFRPG Bestiary","description":"Half-dragons are only rarely the result of dragons mating with other creatures-most are the result of strange magical experiments. In most cases, a successful creation breeds true with others of its kind, as with the dreaded dracolisk.","ecology":"","habitat_society":""},{"name":"Dragonne","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"magical beast","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":20,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+3 Dex, +8 natural, -1 size","hp":76,"hd":"9d10+27","hdvalue":9,"fort":9,"ref":9,"will":2,"speed":[{"type":"land","speed":40},{"type":"fly","speed":30,"maneuverability":"poor"}],"melee":"bite +13 (1d8+5), 2 claws +13 (1d6+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"roar"},{"type":"pounce"}],"strength":21,"dexterity":17,"constitution":17,"intelligence":6,"wisdom":12,"charisma":12,"baseatk":9,"cmb":16,"cmd":26,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Fly","value":5},{"skill":"Perception","value":12}],"languages":["Draconic"],"environments":["temperate deserts"],"organizations":["solitary","pair","pride (5-10)"],"treasure":"standard","description_visual":"This creature has the features of a lion but the wings and scales of a brass dragon, and a wild mane matching its scales.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Roar","kind":"Su","details":"A dragonne can unleash a devastating roar every 1d4 rounds as a standard action. All creatures except dragonnes within 120 ft. must succeed at a DC 17 Fortitude save or become fatigued. Those within 30 ft. who fail their saves are also deafened for 2d4 rounds. This is a sonic effect. The save DC is Constitution-based."}],"description":"Possessing the savage instincts of lions with the cunning of brass dragons, dragonnes combine the fiercest features of these noble creatures into predators both awe-inspiring and deadly.\n\nThe origin of dragonnes generates endless speculation. The odds of these creatures being direct crossbreeds of dragons and lions are quite remote, for numerous reasons: the two creatures rarely share the same territories; few creatures as clever as brass dragons would choose to mate with simple lions; and dragonne abilities differ significantly from those of metallic dragons. While otherworldly breeding experiments and magical mishaps remain possibilities, few satisfying explanations make themselves apparent.\n\nAlthough many creatures rightly fear these ferocious hunters, few dragonnes are blatantly evil-most are just highly territorial and seek to defend their homes and hunting grounds from interlopers. Creatures that draw too close to a dragonne's lair are typically met by the resident's fearsome roar, followed by its claws and fangs if this warning is ignored. Those who attempt to settle in a dragonne's territory find themselves harassed constantly until they decide to leave or the dragonne is slain. These intimidating predators spend the majority of their time on the ground, even when in combat, since their wings prove somewhat ungainly. They typically search for prey and intruders from the air, then land nearby to charge and pounce.\n\nDespite their deadliness, dragonnes form strong bonds with those they consider members of their pride, sometimes even adopting creatures of other races. A character with the Leadership feat can take a dragonne as a cohort. Such characters must have an effective leadership level of 10th. Most dragonne cohorts gain levels in barbarian, fighter, or ranger.\n\nA dragonne measures between 10 and 12 ft. long and weighs up to 1,200 pounds.","ecology":"","habitat_society":""},{"name":"Drider","cr":7,"xp":3200,"alignment":"CE","size":"Large","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"detect good"},{"type":"detect law"},{"type":"detect magic"}],"ac":20,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+2 Dex, +1 dodge, +8 natural, -1 size","hp":76,"hd":"9d8+36","hdvalue":9,"fort":7,"ref":5,"will":8,"immunities":["sleep"],"sr":18,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"mwk heavy mace +9 (1d8+3), bite +3 (1d4+1 plus poison)","ranged":"mwk composite longbow +8 (1d8+2/x3)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"web","details":"+7 ranged, DC 18, hp 9"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect law"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"darkness"},{"spell":"faerie fire"}]},{"frequency":"1/day","spells":[{"spell":"clairaudience/clairvoyance"},{"spell":"deeper darkness"},{"spell":"dispel magic"},{"spell":"levitate"},{"spell":"suggestion"}]}],"spellsknown_caster_level":6,"spellsknown_concentration":14,"spellsknown":[{"spell_level":3,"spell_slots":4,"spells":[{"spell":"lightning bolt"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"invisibility"},{"spell":"web"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"ray of enfeeblement"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"daze"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"ray of frost"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":15,"dexterity":15,"constitution":18,"intelligence":15,"wisdom":16,"charisma":16,"baseatk":6,"feats":[{"feat":"Blind-Fight"},{"feat":"Dodge"},{"feat":"Combat Casting"},{"feat":"Weapon Focus (bite, mace)"}],"skills":[{"skill":"Climb","value":22},{"skill":"Intimidate","value":15},{"skill":"Knowledge (arcana)","value":14},{"skill":"Perception","value":15},{"skill":"Spellcraft","value":14},{"skill":"Stealth","value":14}],"languages":["Common","Elven","Undercommon"],"sq":[{"type":"undersized weapons"}],"environments":["any underground"],"organizations":["solitary","pair","group (3-8)"],"treasure":"double (masterwork heavy mace, masterwork  composite longbow [+2 Str] with 20 arrows, additional treasure)","description_visual":"The dry rasping of spidery legs brings this hideous monstrosity into view-a nightmarish, centaurian fusion of drow and spider.","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 18; frequency 1/round for 6 rounds; effect 1d2 Str; cure 1 save. The save DC is Constitution-based. Spells A drider casts spells as a 6th-level cleric, sorcerer, or wizard, but doesn't gain any other class abilities."},{"type":"Undersized Weapons","kind":"Ex","details":"Although a drider is Large, its upper torso is the same size as that of a Medium humanoid's upper torso. As a result, it wields weapons as if it were one size category smaller than its actual size (Medium for most driders)."}],"description":"Created from the body of a drow, warped and mutated through special poisons and elixirs to take on the characteristics of a giant spider, the drider is a dangerous creature.\n\nDriders are sexually dimorphic. A female drider's lower spider body is sleek and graceful, often similar to a black widow's body, while its upper drow torso retains its alluring curves and beautiful face (with the exception of sharp, poisonous fangs). A male drider's lower body is bulky like a tarantula, while its upper body is wiry and bears a hideous face more spider than drow, complete with fanged mandibles.","ecology":"","habitat_society":""},{"name":"Drocha Swarm","cr":7,"xp":3200,"alignment":"CE","size":"Tiny","type":"undead","subtypes":["incorporeal","swarm"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["fear (30 ft., DC 18, 1d6 rounds)"],"ac":20,"ac_touch":20,"ac_flat_footed":16,"ac_mods":"+4 deflection, +4 Dex, +2 size","hp":76,"hd":"9d8+36","hdvalue":9,"fort":7,"ref":7,"will":5,"defensive_abilities":["incorporeal swarm traits"],"immunities":["undead traits"],"speed":[{"type":"land","speed":0},{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"swarm (4d6 plus blood drain)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"blood drain","details":"1d2 Con"},{"type":"ghost touch jaws"},{"type":"project death"}],"dexterity":18,"wisdom":15,"charisma":19,"baseatk":6,"cmb":19,"cmd":29,"cmd_special":"+4 vs. trip","skills":[{"skill":"Fly","value":16}],"environments":["any"],"organizations":["solitary","pack (2-5)"],"treasure":"none","description_visual":"Hundreds of twisted, distorted faces roil in a miserable cloud, screaming of their unquiet deaths.","source":"AP 75","special_abilities":[{"type":"Ghost Touch Jaws","kind":"Su","details":"A drocha swarm's many biting jaws are considered to have the ghost touch special ability. This allows it to deal its swarm damage to corporeal foes, and to deal normal damage to incorporeal creatures such as ghosts, shadow demons, and even other drocha swarms."},{"type":"Project Death","kind":"Su","details":"As a standard action, a drocha swarm can target a creature within 30 ft. and cry mournful wails that fill the listener with images of its own death. The targeted creature must succeed at a DC 18 Will save to steel itself against this morbid onslaught. If that save fails, the victim must succeed at a Fortitude save or die from fear. Even if the Fortitude save succeeds, the victim takes 4d6 points of damage. A creature that successfully saves against the initial Will save isn't subject to the same drocha swarm's project death ability for 24 hours. This is a mind-affecting fear effect. The save DC is Charisma-based."}],"description":"The opening of the Worldwound brought many horrors to the world, and one of the more tragic and horrible results was the elimination of the Sarkorian people. The mass deaths of these people spawned roiling clouds of unquiet spirits called drocha swarms. Each made of the spirits of hundreds of Sarkorians who died at once, these ghostly swarms reveal the screaming faces of those who once lived and thrived in this verdant land. Their lives were cut short either by the ripping open of the terrain itself or by the demons that subsequently poured forth from the Abyss. Now, these tortured swarms of spirits roam the Worldwound, alone or in packs. Drocha swarms are devoid of the goodliness and respect for nature they had in life. All these tortured souls can do is scream and torment others, and though incorporeal, their razor-sharp teeth materialize just long enough to tear at any creatures they happen across.\n\nMostly translucent, drocha swarms contain only the faintest traces of black and green delineating the writhing mouths and rolling eyes of the faces within. The faces moan independently, creating a cacophony of voices, each shouting rage at its death or screaming for others to listen to the story of its plight. It would be maddening to pick out individual voices and follow their terrible cries. The swarm can expand and contract as necessary, pouring over enemies and draining them of the life drocha swarms were so violently denied, an action that doesn't seem to bring the pitiful creatures any relief from their hideous afterlife.\n\nEcology\n\nIt is postulated drocha swarms can form anywhere death has occurred on a massive scale. Before the Worldwound opened, they were virtually nonexistent in the Inner Sea region, though some theorize the Sodden Lands could have their own form of drocha swarms made up of those who perished when the Eye of Abendego formed and ravaged the Lirgeni people, practically eliminating them from the Inner Sea.\n\nThe dead individuals that make up a drocha swarm have lost any identity they once had and are hideously transformed; they are now horrific vehicles of undeath, created only when the conditions are right. As dead souls trapped on the Material Plane are wont to do, drocha swarms are angry and vengeful, and attack any living thing near them with impunity.\n\nSince these swarms are composed of undead spirits, once reduced to 0 hit points, drocha swarms are immediately destroyed instead of dispersing. Whether these unquiet spirits are then freed from their connection to the Material Plane and are able to pass on to the Boneyard is unclear. Many scholars believe that destroyed drocha swarms don't pass on to their final judgment and instead are flung to different edges of the Worldwound, where they slowly reform. These scholars state that the real tragedy in regard to putting these horrifying beings out of their tortured misery is that those who defeat them are not liberating the tortured souls, but rather just postponing future encounters with new drocha swarms. This theory is telling, for if drocha swarms were indeed destroyed, there would be fewer and fewer of them every year. However, encounters with these deadly swarms have shown no hint of letting up.\n\nHabitat & Society\n\nDrocha swarms typically stay in the area in which they died, repeatedly going over the same territory in an ostensible attempt to understand why the villages and cities in which they lived are no longer there. In contrast, some drocha swarms float all about the Worldwound attacking demons and humanoids alike. When drocha swarms attack demons, their screams and wails change tone and pitch, as if the spirits understand demons were responsible for their demise.\n\nBecause of their roaming nature, these swarms infrequently encounter each other. As unintelligent undead, drocha swarms have no society. Even when swarms come across each other, they seem unaware of each other's existence-which is perhaps unsurprising since drocha swarms focus on living things.\n\nOn rare occasions, drocha swarms have been reported to collide with each other. When this event occurs, a strange thing happens. The two (or more) swarms appear to merge together, the translucent cloud of screaming faces darkening and billowing out in an even more chaotic roil. The screaming faces that float within the deadly mass pass through one another in a twisted dance and the volume of their wails increases to a painfully uncomfortable level. The merged swarm pulses and continues to grow larger than the volume of the two individual drocha swarms. This horrid mass coalesces and ceases flying, coming to rest on the ground, and remaining stationary for hours at a time. During this period, living creatures can actually approach the merged swarm without the drocha swarms pursuing them, though some have reported that pseudopod-like appendages stretch out from the mass and probe the air in the direction of the living. After several hours, the wails and shrieks build to a crescendo loud enough to make one's ears bleed and the area of the swarm's fear aura doubles. Once this happens, the merged cloud of drocha swarms rapidly pulses, then dramatically contracts to the size of a single drocha swarm. It's unknown whether the two merge and take up the same space or one swarm takes over the other. Some believe the two swarms engage in a brutal battle with one another until a single swarm is destroyed. It's believed this is the only way the component spirits can be freed from their tortured existence, but what truly happens in these rare circumstances is unknown.\n\nTo the few untainted individuals who still call the Worldwound home, drocha swarms are as infamous as demons for their ability to cause destruction and turmoil wherever they go. Because they are clearly not demons, however, a few stories have emerged in the hundred years that drocha swarms have existed. Some say the Sarkorians, who nervously predicted the thinness of their realm, deserve their fate for not fleeing. Others say there was no way the Sarkorians could have predicted their fates. Still others claim the Sarkorians are the victims of a greater force, which needed thousands of lives to manifest its evil nature on the Material Plane. Who is correct is anyone's guess.","ecology":"It is postulated drocha swarms can form anywhere death has occurred on a massive scale. Before the Worldwound opened, they were virtually nonexistent in the Inner Sea region, though some theorize the Sodden Lands could have their own form of drocha swarms made up of those who perished when the Eye of Abendego formed and ravaged the Lirgeni people, practically eliminating them from the Inner Sea.\n\nThe dead individuals that make up a drocha swarm have lost any identity they once had and are hideously transformed; they are now horrific vehicles of undeath, created only when the conditions are right. As dead souls trapped on the Material Plane are wont to do, drocha swarms are angry and vengeful, and attack any living thing near them with impunity.\n\nSince these swarms are composed of undead spirits, once reduced to 0 hit points, drocha swarms are immediately destroyed instead of dispersing. Whether these unquiet spirits are then freed from their connection to the Material Plane and are able to pass on to the Boneyard is unclear. Many scholars believe that destroyed drocha swarms don't pass on to their final judgment and instead are flung to different edges of the Worldwound, where they slowly reform. These scholars state that the real tragedy in regard to putting these horrifying beings out of their tortured misery is that those who defeat them are not liberating the tortured souls, but rather just postponing future encounters with new drocha swarms. This theory is telling, for if drocha swarms were indeed destroyed, there would be fewer and fewer of them every year. However, encounters with these deadly swarms have shown no hint of letting up.","habitat_society":"Drocha swarms typically stay in the area in which they died, repeatedly going over the same territory in an ostensible attempt to understand why the villages and cities in which they lived are no longer there. In contrast, some drocha swarms float all about the Worldwound attacking demons and humanoids alike. When drocha swarms attack demons, their screams and wails change tone and pitch, as if the spirits understand demons were responsible for their demise.\n\nBecause of their roaming nature, these swarms infrequently encounter each other. As unintelligent undead, drocha swarms have no society. Even when swarms come across each other, they seem unaware of each other's existence-which is perhaps unsurprising since drocha swarms focus on living things.\n\nOn rare occasions, drocha swarms have been reported to collide with each other. When this event occurs, a strange thing happens. The two (or more) swarms appear to merge together, the translucent cloud of screaming faces darkening and billowing out in an even more chaotic roil. The screaming faces that float within the deadly mass pass through one another in a twisted dance and the volume of their wails increases to a painfully uncomfortable level. The merged swarm pulses and continues to grow larger than the volume of the two individual drocha swarms. This horrid mass coalesces and ceases flying, coming to rest on the ground, and remaining stationary for hours at a time. During this period, living creatures can actually approach the merged swarm without the drocha swarms pursuing them, though some have reported that pseudopod-like appendages stretch out from the mass and probe the air in the direction of the living. After several hours, the wails and shrieks build to a crescendo loud enough to make one's ears bleed and the area of the swarm's fear aura doubles. Once this happens, the merged cloud of drocha swarms rapidly pulses, then dramatically contracts to the size of a single drocha swarm. It's unknown whether the two merge and take up the same space or one swarm takes over the other. Some believe the two swarms engage in a brutal battle with one another until a single swarm is destroyed. It's believed this is the only way the component spirits can be freed from their tortured existence, but what truly happens in these rare circumstances is unknown.\n\nTo the few untainted individuals who still call the Worldwound home, drocha swarms are as infamous as demons for their ability to cause destruction and turmoil wherever they go. Because they are clearly not demons, however, a few stories have emerged in the hundred years that drocha swarms have existed. Some say the Sarkorians, who nervously predicted the thinness of their realm, deserve their fate for not fleeing. Others say there was no way the Sarkorians could have predicted their fates. Still others claim the Sarkorians are the victims of a greater force, which needed thousands of lives to manifest its evil nature on the Material Plane. Who is correct is anyone's guess."},{"name":"Dullahan","cr":7,"xp":3200,"alignment":"LE","size":"Medium","type":"undead","init":2,"senses":[{"type":"blindsight","modifier":"60 ft."}],"auras":["frightful presence (30 ft., DC 19)"],"ac":21,"ac_touch":11,"ac_flat_footed":20,"ac_mods":"+10 armor, +1 Dex","hp":85,"hd":"10d8+40","hdvalue":10,"hp_mods":["fast healing 5"],"fort":7,"ref":5,"will":-2,"defensive_abilities":["channel resistance +4"],"immunities":["undead traits"],"sr":18,"speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"+1 keen longsword +14 (1d8+6/17-20 plus 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"chilling blade"},{"type":"death's calling"},{"type":"summon mount"}],"strength":20,"dexterity":14,"intelligence":14,"wisdom":16,"charisma":18,"baseatk":7,"cmb":12,"cmb_special":"+4 vs. grapple","cmd":17,"cmd_special":"can't be tripped","feats":[{"feat":"Iron Will"},{"feat":"Mounted Combat"},{"feat":"Ride-By Attack"},{"feat":"Trample"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Handle Animal","value":14},{"skill":"Intimidate","value":17},{"skill":"Perception","value":16},{"skill":"Ride","value":7},{"skill":"Spellcraft","value":15},{"skill":"Stealth","value":10}],"languages":["Common","Sylvan"],"environments":["any"],"organizations":["solitary"],"treasure":"double (+1 full plate, +1 longsword)","description_visual":"Clad in ragged black robes and tarnished armor, this grim, headless rider is surrounded by an aura of menace.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Chilling Blade","kind":"Su","details":"A dullahan is proficient with all simple and martial slashing weapons. When it wields a slashing weapon, the blade inflicts +1d6 cold damage and gains the keen weapon property."},{"type":"Death's Calling","kind":"Su","details":"Once per day as a standard action, a dullahan may place death's calling on a target within 60 ft. (DC 22 Fortitude negates). If the dullahan knows and speaks the target's name, the target takes a -2 penalty on the save. If the victim fails the save, he becomes staggered for 1d6 rounds. For the next 24 hours (or until the dullahan is slain), all critical hits against the victim automatically confirm. Finally, the victim automatically fails all Constitution checks to stabilize while dying. This is a mind-affecting curse effect. The save DC is Charisma-based."},{"type":"Summon Mount","kind":"Su","details":"As a standard action, a dullahan can summon a war-trained heavy horse with the fiendish creature simple template. This horse remains until it is slain or the dullahan dismisses it. He can only have one such horse in his service at a time."}],"description":"Terrifying reapers of souls, dullahans are created by powerful fiends from the souls of particularly cruel generals, watch-captains, or other military commanders.\n\nSent back from the pits of Hell to sow terror and harvest new souls, dullahans return to the towns or villages they lived in as mortals. While their favored victims are evil men and women (or their living descendants) whose souls are destined for Hell, the dullahans have no qualms about adding innocents to their lists of victims.\n\nLegends tell of powerful dullahans who can summon not just a single fiendish mount, but an entire carriage pulled by six powerful ebony horses. Known as a \"Coach of the Silent,\" these powerful undead are CR 14 with 20 Hit Dice, the advanced creature simple template, and the ability to cast trap the soul on those who fail to resist their death's calling. These souls take seats in the coach, where they languish forever-or at least until the dullahan himself is slain.","ecology":"","habitat_society":""},{"name":"Duppy","cr":7,"xp":3200,"alignment":"CE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["unnatural aura (30 ft.)"],"ac":20,"ac_touch":20,"ac_flat_footed":14,"ac_mods":"+4 deflection, +6 Dex, +0 natural","hp":76,"hd":"9d8+36","hdvalue":9,"fort":7,"ref":11,"will":4,"defensive_abilities":["channel resistance +2","incorporeal"],"immunities":["undead traits"],"weaknesses":["resurrection vulnerability","sunlight powerlessness"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"incorporeal touch +12 (2d8 negative energy plus 1d6 Str drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"ravenous hounds"}],"dexterity":22,"intelligence":13,"wisdom":15,"charisma":19,"baseatk":6,"cmb":7,"cmd":17,"feats":[{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Step Up"}],"skills":[{"skill":"Fly","value":26},{"skill":"Intimidate","value":16},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":18}],"languages":["Common","Polyglot"],"environments":["warm coastlines"],"organizations":["solitary","pair","pack (3-8)"],"treasure":"none","description_visual":"This floating, ghostly humanoid wears a cowl, but the face beneath it is a blend of human and animal, radiating hatred and fury. Transparent, canine shapes twine around its legs.","source":"Isles Of The Shackles","special_abilities":[{"type":"Ravenous Hounds","kind":"Sp","details":"Once per day as a standard action, a duppy can bring into being a pack of incorporeal hounds for 1d4+3 rounds. The ravenous hounds attack as a single unit, have a +11 attack bonus, deal 2d6+3 points of force damage on a successful hit, and threaten a critical hit on a natural 20. This ability is otherwise identical to mage's sword (CL 7th)."},{"type":"Resurrection Vulnerability","kind":"Su","details":"A raise dead or similar spell cast on a duppy destroys it (Will negates). Using the spell in this way doesn't require a material component."},{"type":"Strength Drain","kind":"Su","details":"Creatures hit by a duppy's touch attack must succeed at a DC 18 Fortitude save or take 1d6 points of Strength drain. On each successful attack, the duppy gains 5 temporary hit points. The save DC is Charisma-based."},{"type":"Unnatural Aura","kind":"Su","details":"Animals don't willingly approach the creature unless the animal's master succeeds at a DC 25 Handle Animal, Ride, or wild empathy check.."}],"description":"A duppy is the spirit of a cruel and brutal sailor who died by violence on land, away from his ship and crew, and thus was unable to receive a proper burial at sea. While its ghostly form is evidence enough of its twisted hatred, a duppy also possesses power over a pack of faithful, otherworldly hounds that share in their master's malignance. Duppies typically seek out sailors and pirates to exact their vengeance on, seeking to inf lict great violence on those living creatures who remind them of what they lost in life. For this reason, duppies are most often found in seaside towns or nearby beaches, and settlements that rely on the ocean know to fear and hate these ghastly beings.\n\nThe presence of a duppy is often preceded by the distant sound of unearthly howling. While a duppy's incorporeal form ensures that it cannot be captured via mundane means, those who do manage to trick a duppy into a trap are wise to keep the horror confined until day, when its otherworldly abilities are hindered and it can be more easily defeated. However, few creatures can muster powers strong enough to cage a duppy, whose hounds confound enemies and allow the ghostly monster to attack victims from all sides.","ecology":"","habitat_society":""},{"name":"Dweomercat","cr":7,"xp":3200,"alignment":"CN","size":"Medium","type":"magical beast","init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":23,"ac_touch":17,"ac_flat_footed":16,"ac_mods":"+6 Dex, +1 dodge, +6 natural","hp":85,"hd":"10d10+30","hdvalue":10,"fort":10,"ref":13,"will":2,"dr":"5/magic","sr":19,"speed":[{"type":"land","speed":40}],"melee":"2 claws +16 (1d4+2), bite +16 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"dweomer leap"},{"type":"pounce"},{"type":"rake","details":"2 claws +11, 1d4+2"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"dispel magic"},{"spell":"lesser globe of invulnerability"}]},{"frequency":"3/day","spells":[{"spell":"antimagic field"},{"spell":"dimension door","details":"self only"}]}],"strength":15,"dexterity":23,"constitution":16,"intelligence":13,"wisdom":16,"charisma":16,"baseatk":10,"cmb":3,"cmd":13,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":6},{"skill":"Knowledge (arcana)","value":11},{"skill":"Perception","value":16},{"skill":"Stealth","value":19}],"languages":["Common","Sylvan"],"sq":[{"type":"spell link"}],"environments":["any forests (First World)"],"organizations":["solitary","hunt (2-3)","ambush (1-3 dweomercats and 2-12 dweomercat cubs)"],"treasure":"standard","description_visual":"Its coat shining vividly, this majestic tiger looks exotic and otherworldly. It gazes with piercing yellow eyes and stands calmly, as though fearless.","source":"AP 36","special_abilities":[{"type":"Spell Link","kind":"Su","details":"When a dweomercat is targeted by a spell or within the area of effect of a spell, it can, as a swift action, forgo its dweomer leap ability to gain an effect related to the school of the spell targeting it. This effect activates before the dweomercat is affected by the spell targeting it and regardless of whether or not the spell overcomes its spell resistance. Each power lasts for 1 minute per level of the spell targeting the dweomercat, until the dweomercat uses this ability again, or until the dweomercat chooses to dismiss the effect as a free action, whichever duration is shortest. This ability doesn't prevent the spell affecting the dweomercat from taking effect; it only provides an additional benefit. Abjuration: Gains acid, cold, fire, electricity, or sonic resistance equal to 2 per spell level. Conjuration: Gains a deflection bonus to AC equal to +1 for every 5 levels of the spell. Divination: Gains the effects of detect chaos, evil, good, or law. Enchantment: Grants the effects of the spell heroism. Evocation: Inflicts an amount of damage equal to the spell's level upon the spell's caster. Illusion: Grants the effects of invisibility. This effect ends as per the spell. Necromancy: Gains the effects of false life, as if cast by the opposing spell's caster. Transmutation: Gains an enhancement bonus on its natural weapons equal to +1 for every 5 levels of the spell.."}],"description":"Powerful and regal, dweomercats stalk the First World, preying upon lesser creatures, but more voraciously hunting new and ever stranger sources of magic. Beings as much composed of sculpted arcane eddies as of flesh and blood, these capricious felines flourish along the intangible ley lines of their home realm, drinking in its weird powers as a plant thrives on light. Yet even more potent than their thirst for magic and the euphoria they draw from being in proximity to the reshaping of reality is dweomercats' racial curiosity, which leads them endlessly across the First World-and often beyond. The average adult dweomercat is about 4 ft. tall and 7 ft. long, weighing over 250 pounds, while their cubs are approximately 1 foot tall and weigh no more than 15 pounds. Ecology A newly born dweomercat cub is connected to its homeland by only a thin tether of fey magic, and can only tap into its true potential during the instant a spell is cast upon it. The burst of magical energy brought forth by a freshly cast spell momentarily intensifies the bond between the First World and the dweomercat. This link manifests itself clumsily as a sort of sudden teleportation that heaves the fey cat through space and time toward the source of the spell, fueled by the magnetic reaction between the dweomercat and the magic's origin. A dweomercat grows not by the passage of time, but through direct exposure to fey magic. Thus, a dweomercat cub on the Material Plane is stunted developmentally. Though it ages and gains experience and practical wisdom anywhere, only by spending several lifetimes on the First World can the cub reach adulthood. Once it has reached this stage, however, a fully grown dweomercat may freely travel between its native land and the Material Plane without adverse effects. Habitat & Society In the First World, dweomercats travel in packs while hunting. Beyond this predatory advantage, however, they have little use for organized society, as the evershifting nature of their homeland impedes it anyway. Dweomercats that are born on or come to be stranded on the Material Plane are often forced to live on their own. Cut off from the direct magical eddies of the First World, dweomercat cubs prove unable to grow into adults. While they might become slightly stronger and more learned, they never reach the size and prowess of those constantly subjected to the magic of their homeland. Were a dweomercat cub to return to the First World, it would eventually grow into a normal dweomercat, but only over the course of numerous humanoid lifespans. Those dweomercats marooned on the Material Plane seek out areas of great age, changeability, and magical potency- lands most like the First World. Sometimes this means not a specific place, but rather a period spent journeying with a mortal spellcaster. While an adult dweomercat would scoff at the idea of following a humanoid's orders, adolescents see the benefit of journeying alongside an intelligent creature native to the alien world. Should a dweomercat cub find a magic-user reckless or whimsical enough to keep its attention, it might join the caster as a familiar, gaining a measure of constant magical exposure from the intangible connection inherent in such a mystical relationship. Dweomercat Cubs as Familiars Attracted to flashy displays of magic and the strange powers inherent in a bond between a magic-user and her familiar, a dweomercat cub that's wandered from the First World might find its taste for magic and adventure satisfied in the service of a particularly whimsical or ostentatious arcane spellcaster. A spellcaster with the Improved Familiar feat can acquire a chaotic neutral dweomercat cub at 7th level or higher. Should the spellcaster settle into a life of research and predictability for a span of months, the dweomercat cub familiar might take to wandering off and, eventually, might not return-deliberately severing the master-familiar bond and freeing the spellcaster to summon a new familiar.","ecology":"A newly born dweomercat cub is connected to its homeland by only a thin tether of fey magic, and can only tap into its true potential during the instant a spell is cast upon it. The burst of magical energy brought forth by a freshly cast spell momentarily intensifies the bond between the First World and the dweomercat. This link manifests itself clumsily as a sort of sudden teleportation that heaves the fey cat through space and time toward the source of the spell, fueled by the magnetic reaction between the dweomercat and the magic's origin. A dweomercat grows not by the passage of time, but through direct exposure to fey magic. Thus, a dweomercat cub on the Material Plane is stunted developmentally. Though it ages and gains experience and practical wisdom anywhere, only by spending several lifetimes on the First World can the cub reach adulthood. Once it has reached this stage, however, a fully grown dweomercat may freely travel between its native land and the Material Plane without adverse effects.","habitat_society":"In the First World, dweomercats travel in packs while hunting. Beyond this predatory advantage, however, they have little use for organized society, as the evershifting nature of their homeland impedes it anyway. Dweomercats that are born on or come to be stranded on the Material Plane are often forced to live on their own. Cut off from the direct magical eddies of the First World, dweomercat cubs prove unable to grow into adults. While they might become slightly stronger and more learned, they never reach the size and prowess of those constantly subjected to the magic of their homeland. Were a dweomercat cub to return to the First World, it would eventually grow into a normal dweomercat, but only over the course of numerous humanoid lifespans. Those dweomercats marooned on the Material Plane seek out areas of great age, changeability, and magical potency- lands most like the First World. Sometimes this means not a specific place, but rather a period spent journeying with a mortal spellcaster. While an adult dweomercat would scoff at the idea of following a humanoid's orders, adolescents see the benefit of journeying alongside an intelligent creature native to the alien world. Should a dweomercat cub find a magic-user reckless or whimsical enough to keep its attention, it might join the caster as a familiar, gaining a measure of constant magical exposure from the intangible connection inherent in such a mystical relationship. Dweomercat Cubs as Familiars Attracted to flashy displays of magic and the strange powers inherent in a bond between a magic-user and her familiar, a dweomercat cub that's wandered from the First World might find its taste for magic and adventure satisfied in the service of a particularly whimsical or ostentatious arcane spellcaster. A spellcaster with the Improved Familiar feat can acquire a chaotic neutral dweomercat cub at 7th level or higher. Should the spellcaster settle into a life of research and predictability for a span of months, the dweomercat cub familiar might take to wandering off and, eventually, might not return-deliberately severing the master-familiar bond and freeing the spellcaster to summon a new familiar."},{"name":"Ebon Acolytus","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":8,"ac_flat_footed":20,"ac_mods":"-1 Dex, +12 natural, -1 size","hp":79,"hd":"9d10+30","hdvalue":9,"fort":3,"ref":2,"will":3,"immunities":["construct traits"],"speed":[{"type":"land","speed":30}],"melee":"dagger +14 (1d6+9/19-20) or 2 slams +14 (1d6+6)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"prostration"},{"type":"sacrifice"}],"strength":22,"dexterity":8,"constitution":10,"intelligence":10,"wisdom":11,"charisma":1,"baseatk":9,"cmb":16,"cmd":25,"environments":["any"],"organizations":["solitary"],"treasure":"incidental","description_visual":"A chilling statue strands behind a dark altar, both smeared with evidence of grisly sacrifices. The monstrous statue, sculpted as a perverse amalgam of both man and beast, raises a wickedly curved sacrificial dagger above its head, its bejeweled eyes seeming to glint with murderous zeal.","source":"AP 30","special_abilities":[{"type":"Prostration","kind":"Ex","details":"As a standard action, an ebon acolytus can attempt to force any creature it is currently grappling into a sacrificial position. The construct must make an additional combat maneuver check against its target to reposition it into an advantageous position. If it succeeds, and the victim remains grappled at the beginning of the construct's next round, the ebon acolytus may make use of its sacrifice ability. An ebon acolytus gains a +2 bonus on its CMB for the purposes of making this check if it is adjacent to an altar or similar site of ceremonial bloodletting."},{"type":"Sacrifice","kind":"Su","details":"As a full-round action, an ebon acolytus may make a coup de grace attack with its dagger against any target currently grappled into place using its prostration ability. The target is affected by the coup de grace attack and must make a Fortitude saving throw (DC 10 + damage dealt) or die as normal. If the target is killed by this attack, his soul is sent straight to the plane of the being to which the altar is dedicated, regardless of alignment, and cannot be raised from the dead except by a cleric sworn to the same deity or by a miracle or wish spell. A creature under the effects of a protection from evil spell-or similar spell that opposes the alignment of the god the ebon acolytus is crafted to serve-may be resurrected as normal."}],"description":"Dedicated to dark gods, fiends hungry for the souls of innocents, and even more monstrous beings, ebon acolyti- sometimes called altar golems-are terrifying constructs, for they are not designed merely to kill, but to aid in the often bloody work required in the service of foul divinities. Carved from a single block of stone or other sturdy material, these constructs resemble towering statues, crafted to appear as servants of specific deities and often etched with icons sacred to their worship. In addition to its fearful body, an ebon acolytus is typically crafted with a companion altar, upon which it might aid its master or an unholy congregation in dark rites and ritual bloodletting. The exact height and weight of an ebon acolytus varies, largely depending on the shape of its body and the quality of the stone used in its creation, though most rise to around 14 ft. tall and weigh around 2,500 pounds. Some carry Large sacrificial weapons other than daggers, but these prove rare and vary between faiths. Ecology As artificial creations, ebon acolyti have no bodily needs or functions. This allows them to perform well as both grim altar attendants and as defenders of unholy sites. Clandestine cults often go to great lengths to create ebon acolyti just for this reason, as such groups' survivals rely upon the secretiveness of their worship. In some rare instances, especially old and well-used ebon acolyti have been known to defy their creators, but only when such masters have defied the will or tenets of their deity. Religious figures claim such rarities are not a sign of devotion from the constructs themselves, though, but instead a manifestation of a deities' will operating through a convenient medium. Habitat & Society Altar golems are typically found in places of dark worship, from the expected locations like depraved dungeons and temples consecrated in the name of sinister gods to hidden shrines under the homes of supposedly reputable neighbors or secret mountain hollows. Wherever the perverse will of foul deities takes root, there ebon acolyti might be found. An ebon acolytus's most feared ability is its power to sacrifice living creatures to the dark entity to whom it is devoted. This foul capability rises from a series of profane rites conducted as part of the construct's creation, during which it is bound to a specific patron. A ebon acolytus cannot be reconsecrated to a different deity, and those it sacrifices always appear in the same extraplanar realm. The being an ebon acolytus is created to serve must be of at least deity-level power, and all attempts to create servants that direct souls to a lesser or more vague source fail. Thus, ebon acolyti are typically found dedicated to evil gods, demon lords, archdevils, one of the four horsemen, or similar beings. Those killed by an ebon acolytus prove exceedingly diffcult to recover, except by the power of those devoted to the deity to whom the victim was sacrificed. As such, foul priests often employ ebon acolyti to gain bargaining chips, having their construct minion sacrifice a being and demanding some service should the victim's loved ones wish him returned. Alternately, worshipers of notorious deities often face worldly retribution, but might escape tenacious pursuers by sacrificing themselves to their deity, their sacrificial deaths allowing them to forever elude the magic and vengeance of their foes. Occasionally, there are those who seek to track down and reclaim souls wrongfully slain by ebon acolyti. Many quests to unholy realms have been undertaken in the attempt to rescue such damned souls, though few meet with any success. Although most discussion of ebon acolyti connects them with foul deities, such need not be the case. Tools first and foremost, these constructs might serve non-evil gods, though in most cases their murderous aptitudes are ill suited to such worship. In some cases, particularly in the instances of exotic and little-known deities who prove both benevolent and bloodthirsty, ebon acolyti might be found in the service of goodly faiths, though such instances are exceedingly rare. Construction An ebon acolytus is chiseled from a single block of dark stone, often black granite or marble, jade, or some other lustrous material, and weighing at least 4,000 pounds. The stone must be of exceptional quality and costs at least 6,000 gp. Ebon Acolytus CL 11th; Price 24,000 gp CONSTRUCTION Requirements Craft Construct, animate objects, desecrate, trap the soul, creator must be caster level 11th; Skill Craft (sculpting) or Craft (stonemasonry) DC 16; Cost 12,000 gp Ebon Acolyti on Golarion Though rare, ebon acolyti have been found throughout Golarion, consecrated to a host of foul patrons. While many watch over temples and holy sites of Rovagug, Lamashtu, and Asmodeus-and peripheral shines to his archdevils-they are more commonly found in squalid holes where demon and daemon worshipers enact their blasphemous ceremonies. Below are two particularly infamous ebon acolyti. The Altar of Angazhan: Deep in the Mwangi Expanse lies an ebon acolytus dedicated to the demon lord Angazhan, the Ravener King and Lord of Apes. Carved from obsidian, the altar resembles Angazhan himself, a brutish ape with savage tusks and six long, slender fingers. Unlike other altar golems, the Altar of Angazhan speaks through the Voice of Angazhan, the animated and endlessly furious skull of a massive gorilla that serves as the construct's head. Although the skull possesses only the intellect of an average ape, it \"leads\" a pack of charau-ka that worships it as their god. The tribe's shamans interpret their lord's will in his endless grunts and howls, directing their people to scour the Expanse for food, riches, and sacrificial victims. The Midnight Temple of Egorian: Found in Cheliax's infernal capital, this massive, marble-carved ebon acolytus is known as the Black Altar. Shaped into the likeness of a humanoid devil with sweeping horns and monstrous wings, the Black Altar seems to be carved straight from the layers of Hell itself. At the stroke of midnight on the first day of every ninth week, nine slaves are sacrificed here to the God Fiend, the Black Altar absorbing their blood and sending their souls screaming to Asmodeus. When the altar prepares to kill its victims, its great wings close so none can see the final blow, and when they open again, nothing of the sacrifice remains.","ecology":"As artificial creations, ebon acolyti have no bodily needs or functions. This allows them to perform well as both grim altar attendants and as defenders of unholy sites. Clandestine cults often go to great lengths to create ebon acolyti just for this reason, as such groups' survivals rely upon the secretiveness of their worship. In some rare instances, especially old and well-used ebon acolyti have been known to defy their creators, but only when such masters have defied the will or tenets of their deity. Religious figures claim such rarities are not a sign of devotion from the constructs themselves, though, but instead a manifestation of a deities' will operating through a convenient medium.","habitat_society":"Altar golems are typically found in places of dark worship, from the expected locations like depraved dungeons and temples consecrated in the name of sinister gods to hidden shrines under the homes of supposedly reputable neighbors or secret mountain hollows. Wherever the perverse will of foul deities takes root, there ebon acolyti might be found. An ebon acolytus's most feared ability is its power to sacrifice living creatures to the dark entity to whom it is devoted. This foul capability rises from a series of profane rites conducted as part of the construct's creation, during which it is bound to a specific patron. A ebon acolytus cannot be reconsecrated to a different deity, and those it sacrifices always appear in the same extraplanar realm. The being an ebon acolytus is created to serve must be of at least deity-level power, and all attempts to create servants that direct souls to a lesser or more vague source fail. Thus, ebon acolyti are typically found dedicated to evil gods, demon lords, archdevils, one of the four horsemen, or similar beings. Those killed by an ebon acolytus prove exceedingly diffcult to recover, except by the power of those devoted to the deity to whom the victim was sacrificed. As such, foul priests often employ ebon acolyti to gain bargaining chips, having their construct minion sacrifice a being and demanding some service should the victim's loved ones wish him returned. Alternately, worshipers of notorious deities often face worldly retribution, but might escape tenacious pursuers by sacrificing themselves to their deity, their sacrificial deaths allowing them to forever elude the magic and vengeance of their foes. Occasionally, there are those who seek to track down and reclaim souls wrongfully slain by ebon acolyti. Many quests to unholy realms have been undertaken in the attempt to rescue such damned souls, though few meet with any success. Although most discussion of ebon acolyti connects them with foul deities, such need not be the case. Tools first and foremost, these constructs might serve non-evil gods, though in most cases their murderous aptitudes are ill suited to such worship. In some cases, particularly in the instances of exotic and little-known deities who prove both benevolent and bloodthirsty, ebon acolyti might be found in the service of goodly faiths, though such instances are exceedingly rare. Construction An ebon acolytus is chiseled from a single block of dark stone, often black granite or marble, jade, or some other lustrous material, and weighing at least 4,000 pounds. The stone must be of exceptional quality and costs at least 6,000 gp. Ebon Acolytus CL 11th; Price 24,000 gp CONSTRUCTION Requirements Craft Construct, animate objects, desecrate, trap the soul, creator must be caster level 11th; Skill Craft (sculpting) or Craft (stonemasonry) DC 16; Cost 12,000 gp Ebon Acolyti on Golarion Though rare, ebon acolyti have been found throughout Golarion, consecrated to a host of foul patrons. While many watch over temples and holy sites of Rovagug, Lamashtu, and Asmodeus-and peripheral shines to his archdevils-they are more commonly found in squalid holes where demon and daemon worshipers enact their blasphemous ceremonies. Below are two particularly infamous ebon acolyti. The Altar of Angazhan: Deep in the Mwangi Expanse lies an ebon acolytus dedicated to the demon lord Angazhan, the Ravener King and Lord of Apes. Carved from obsidian, the altar resembles Angazhan himself, a brutish ape with savage tusks and six long, slender fingers. Unlike other altar golems, the Altar of Angazhan speaks through the Voice of Angazhan, the animated and endlessly furious skull of a massive gorilla that serves as the construct's head. Although the skull possesses only the intellect of an average ape, it \"leads\" a pack of charau-ka that worships it as their god. The tribe's shamans interpret their lord's will in his endless grunts and howls, directing their people to scour the Expanse for food, riches, and sacrificial victims. The Midnight Temple of Egorian: Found in Cheliax's infernal capital, this massive, marble-carved ebon acolytus is known as the Black Altar. Shaped into the likeness of a humanoid devil with sweeping horns and monstrous wings, the Black Altar seems to be carved straight from the layers of Hell itself. At the stroke of midnight on the first day of every ninth week, nine slaves are sacrificed here to the God Fiend, the Black Altar absorbing their blood and sending their souls screaming to Asmodeus. When the altar prepares to kill its victims, its great wings close so none can see the final blow, and when they open again, nothing of the sacrifice remains."},{"name":"Elasmosaurus","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":20,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+2 Dex, +1 dodge, +9 natural, -2 size","hp":105,"hd":"10d8+60","hdvalue":10,"fort":14,"ref":9,"will":6,"speed":[{"type":"land","speed":20},{"type":"swim","speed":50}],"melee":"bite +13 (2d8+12)","space":"15 ft.","reach":"20 ft.","strength":26,"dexterity":15,"constitution":20,"intelligence":2,"wisdom":13,"charisma":9,"baseatk":7,"cmb":17,"cmd":30,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":14},{"skill":"Swim","value":16}],"environments":["warm aquatic"],"organizations":["solitary","pair","school (3-6)"],"treasure":"none","description_visual":"Long-necked and long-tailed, this large, predatory reptile glides through the water on four powerful flippers.","group":"Dinosaur","source":"PFRPG Bestiary","description":"The sleek elasmosaurus is a long-necked, aquatic reptile. Although not technically a dinosaur, they and their kind are often found hunting in oceans and lakes in areas where dinosaurs are more common. You can create statistics for smaller, similar aquatic reptiles (such as the pleisosaurus) by applying the young simple template to the statistics presented above. An elasmosaurus is 45 ft. long and weighs 4,000 pounds.","ecology":"","habitat_society":""}];
